tool_input.command:
python3 - <<'EOF'
import re
p='src/art/stage.ts'
s=open(p,encoding='utf8').read()
s=s.replace("""  lights: [x: number, y: number, c: 'warm' | 'cold', o: number][];""","""  /** Blinking lights; with a prop name, x/y are relative to that prop's top-left. */
  lights: [x: number, y: number, c: 'warm' | 'cold', o: number, of?: string][];""")
s=s.replace("""  /** A 2-frame flag at a pole tip: left x, top y. */
  flag?: [number, number];
  /** A small group that bobs (smoke, a bird). */
  bob?: Dot[];
  /** Hero path from the lead's door. */
  door?: [x: number, y: number];""","""  /** Hand-typed details attached to a prop (relative to its top-left). */
  attached?: { of: string; dots: Dot[] }[];
  /** A 2-frame flag at a pole tip, relative to the lead's top-left. */
  flag?: [number, number];
  /** A small group that bobs (smoke, a bird); relative to a prop when `of` is set. */
  bob?: { of?: string; dots: Dot[] };
  /** Hero path from the lead's door: x offset in the lead, starting at its base. */
  door?: number;""")
# resolver after spriteDots block: insert before 'const spriteDots'
s=s.replace("""  const focalAll = [s.lead, ...s.focal];
  const flag = s.flag""","""  const focalAll = [s.lead, ...s.focal];
  const byName = (name?: string): [number, number] => {
    if (!name) return [0, 0];
    const p = [...s.props, ...focalAll].find((q) => q.v.name === name);
    if (!p) throw new Error(`No prop named ${name} in ${s.id}`);
    return [p.x, baseOf(p) - p.v.rows.length];
  };
  const shift = (d: Dot[], [ox, oy]: [number, number]) => d.map(([x, y, c, w]) => [x + ox, y + oy, c, w] as Dot);
  const [lx0, ly0] = byName(s.lead.v.name);
  const fl = s.flag ? [lx0 + s.flag[0], ly0 + s.flag[1]] : null;
  const door: [number, number] | null = s.door !== undefined ? [s.lead.x + s.door, baseOf(s.lead)] : null;
  const lights = s.lights.map(([x, y, c, o, of]) => {
    const [ox, oy] = byName(of);
    return light(x + ox, y + oy, c, o);
  });
  const attached = (s.attached ?? []).flatMap((a) => shift(a.dots, byName(a.of)));
  const bobDots = s.bob ? shift(s.bob.dots, byName(s.bob.of)) : [];
  const flag = fl""")
s=s.replace("s.flag[0], s.flag[1]","fl[0], fl[1]").replace("s.flag[0], s.flag[1] + 1","fl[0], fl[1] + 1").replace("s.flag[0], s.flag[1] + 2","fl[0], fl[1] + 2").replace("s.flag[0] + 5, s.flag[1] + 5","fl[0] + 5, fl[1] + 5")
s=s.replace("""    s.door ? path(...s.door) : '',""","""    door ? path(...door) : '',""")
s=s.replace("""    s.lights.map(([x, y, c, o]) => light(x, y, c, o)).join(''),""","""    lights.join(''),""")
s=s.replace("""    dot(s.details),""","""    dot(s.details),
    dot(attached),""")
s=s.replace("""    s.bob ? `<g class="bob" style="--bob:${-4 / s.unitPx}px">${dot(s.bob)}</g>` : '',""","""    bobDots.length ? `<g class="bob" style="--bob:${-4 / s.unitPx}px">${dot(bobDots)}</g>` : '',""")
s=s.replace("""  const scene = s.details.length + (s.bob?.length ?? 0);""","""  const scene = s.details.length + attached.length + bobDots.length;""")
s=s.replace("""      pathEnd: s.door ? pathEnd(...s.door) : undefined,""","""      pathEnd: door ? pathEnd(...door) : undefined,""")
open(p,'w',encoding='utf8').write(s)
EOF
grep -n "s.flag\|s.door\|s.bob" src/art/stage.ts
